<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import { useSkyStore } from '../../stores/sky'
import { useOperationPage } from '../../composables/useOperationPage'
import { opsRead, opsWrite, type OpsRow } from '../../api/operations'
import OperationsTable from './OperationsTable.vue'
import CommuteCreateForm from './CommuteCreateForm.vue'
const sky = useSkyStore(), { rows, page, total, busy, error, notice, act } = useOperationPage(() => '/flights')
const detail = shallowRef<OpsRow>(), seats = shallowRef(1), requestId = shallowRef(crypto.randomUUID() as string)
const changing = shallowRef<OpsRow>(), departure = shallowRef(''), reason = shallowRef('')
const bookings = computed(() => (detail.value?.bookings as OpsRow[] | undefined) ?? [])
watch(seats, () => { requestId.value = crypto.randomUUID() })
async function open(row: OpsRow) { await act(async () => { detail.value = await opsRead<OpsRow>(`/flights/${encodeURIComponent(String(row.id))}`); requestId.value = crypto.randomUUID() }) }
async function create(input: unknown) { await act(() => opsWrite('/flights', input)) }
async function book() { if (!detail.value) return; const id = String(detail.value.id); await act(async () => { await opsWrite(`/flights/${encodeURIComponent(id)}/bookings`, { seats: seats.value, requestId: requestId.value }); detail.value = await opsRead<OpsRow>(`/flights/${id}`); requestId.value = crypto.randomUUID() }) }
async function unbook(id: string) { if (!detail.value) return; const flightId = String(detail.value.id); await act(async () => { await opsWrite(`/bookings/${encodeURIComponent(id)}/cancel`); detail.value = await opsRead<OpsRow>(`/flights/${flightId}`) }) }
async function action(row: OpsRow, action: string) { await act(async () => { await opsWrite(`/flights/${encodeURIComponent(String(row.id))}/${action}`, { expectedRevision: row.revision, reason: reason.value, ...(action === 'delay' ? { departureAt: departure.value.length === 16 ? departure.value + ':00' : departure.value } : {}) }); changing.value = undefined; detail.value = undefined; await sky.refresh().catch(() => {}) }) }
</script>
<template><section><h2>空中通勤 · 班次与预约</h2><p>座位为仿真预约名额，不收集乘客身份或支付信息。锁定名单后才生成通勤任务，随后手动分配与执行；起飞窗口为计划出发前5分钟至后15分钟。</p><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="notice" :title="notice" type="success" :closable="false" /><CommuteCreateForm :stations="sky.snapshot.stations" :disabled="busy || !sky.canOperate" @create="create" />
  <OperationsTable :rows="rows" :total="total" :page="page" :busy="busy" :columns="[{key:'title',label:'班次'},{key:'departureAt',label:'计划出发'},{key:'arrivalAt',label:'计划到达'},{key:'bookedSeats',label:'已订座位'},{key:'seats',label:'容量'},{key:'taskStatus',label:'任务状态'},{key:'arrivedAt',label:'仿真到达时间'}]" @page="page = $event"><template #actions="{ row }"><el-button :disabled="busy" @click="open(row)">预约 / 详情</el-button><el-button v-if="row.status === 'scheduled'" :disabled="busy || !sky.canOperate" @click="changing = row; reason = ''; departure = ''">改时 / 激活 / 取消</el-button><RouterLink v-if="row.taskId" to="/task-management">执行任务</RouterLink></template></OperationsTable>
  <el-dialog :model-value="!!detail" title="座位预约" width="min(850px,94vw)" :show-close="!busy" @close="detail = undefined"><template v-if="detail"><p>{{ detail.title }} · 名额 {{ detail.bookedSeats }}/{{ detail.seats }} · {{ detail.status }}</p><el-input-number v-model="seats" :min="1" :max="20" /><el-button :disabled="busy || !sky.canOperate || !!detail.taskId || detail.status !== 'scheduled'" @click="book">预约座位</el-button><el-table :data="bookings"><el-table-column prop="id" label="预约编号" /><el-table-column prop="seats" label="座位" /><el-table-column prop="createdBy" label="预约账号" /><el-table-column prop="status" label="状态" /><el-table-column label="操作"><template #default="{ row }"><el-button v-if="row.createdBy === sky.username && row.status === 'confirmed' && !detail.taskId" :disabled="busy || !sky.canOperate" @click="unbook(String(row.id))">取消预约</el-button></template></el-table-column></el-table></template></el-dialog>
  <el-dialog :model-value="!!changing" title="班次调度" :close-on-click-modal="!busy" :show-close="!busy" @close="changing = undefined"><template v-if="changing"><p>激活会锁定预约名单并生成一个待分配任务；不会自动起飞。取消会取消未起飞任务及其预约。</p><el-input v-model="reason" maxlength="500" placeholder="操作原因" /><label>调整出发时间<input v-model="departure" type="datetime-local"></label><el-button :disabled="busy || !reason.trim() || !departure" @click="action(changing, 'delay')">保存新时间</el-button><el-button :disabled="busy || !reason.trim() || !!changing.taskId" @click="action(changing, 'activate')">锁定名单并创建任务</el-button><el-button type="warning" :disabled="busy || !reason.trim()" @click="action(changing, 'cancel')">取消班次</el-button></template></el-dialog>
</section></template>
